function fitxaDe(u, n){
  const c = CATALEG[u]; return (c && c[n]) ? c[n] : null;
}
function etiquetaDe(u, n){
  const f = fitxaDe(u, n);
  return (f && f.a) ? 'Act. ' + n : 'Ex. ' + n;
}
